<template>
  <view class="practice-page">
    <SiteHeader active="discover" />
    <view class="shell"><view class="page-kicker">AINPE · 从看到做到</view><view class="page-title">选一个方向，动手试试。</view><view class="page-subtitle">方向测试、业务实践与视频需求单；输入只保存在当前设备。</view>
      <scroll-view class="nav-scroll" scroll-x><view class="nav"><view v-for="item in tabs" :key="item.id" :class="['nav-item',{active:view===item.id}]" @click="view=item.id">{{ item.label }}</view></view></scroll-view>

      <view v-if="view==='quiz'" class="panel">
        <view v-if="quizStep<0"><text class="eyebrow">AI DIRECTION / 方向探索</text><view class="panel-title">你的 AI 下一步，从哪里开始？</view><view class="muted">回答 5 个关于目标和兴趣的问题，找到可以先看的真实案例。测试是阅读参考，不代表适配或收益保证。</view><button class="primary" @click="quizStep=0">开始探索 →</button></view>
        <view v-else-if="quizStep<questions.length"><view class="quiz-head"><text @click="quizStep--">← 上一步</text><text>{{ quizStep+1 }} / {{ questions.length }}</text></view><text class="eyebrow">{{ questions[quizStep].eyebrow }}</text><view class="panel-title">{{ questions[quizStep].title }}</view><view class="muted">选择最接近你目前情况的一项，之后可以重新选择。</view><view class="options"><view v-for="opt in questions[quizStep].options" :key="opt.value" :class="['option',{selected:answers[questions[quizStep].id]===opt.value}]" @click="answers[questions[quizStep].id]=opt.value"><view><view class="option-title">{{ opt.label }}</view><view class="option-detail">{{ opt.detail }}</view></view><text>{{ answers[questions[quizStep].id]===opt.value?'✓':'›' }}</text></view></view><button class="primary" :disabled="!answers[questions[quizStep].id]" @click="quizStep++">{{ quizStep===questions.length-1?'查看我的方向':'下一题' }} →</button></view>
        <view v-else><text class="eyebrow">YOUR DIRECTION</text><view class="panel-title">先从感兴趣的方向开始。</view><view class="muted">方向排序根据你的目标、兴趣和基础计算；时间与投入偏好用于下面的阅读建议，不代表收益或项目适配保证。</view><view v-for="(match,i) in recommendations" :key="match.id" class="recommend"><view class="recommend-top">{{ i===0?'优先看看':'备选方向' }} · 0{{ i+1 }}</view><view class="recommend-title">{{ match.title }}</view><view class="muted">{{ match.reason }}</view><view v-if="match.article" class="recommend-article" @click="openArticle(match.article)">{{ match.article.title }} <text>↗</text></view><view v-else class="muted">当前尚未收录可匹配案例。</view></view><view class="reading-hint"><strong>下一步，按你的节奏来。</strong><view>{{ readingHint }}</view></view><button class="secondary" @click="restartQuiz">重新测一次</button><view class="privacy">你的答案只用于本次推荐，不上传。</view></view>
      </view>

      <view v-if="view==='fde'" class="panel"><text class="eyebrow">PRACTICE CARD / FDE</text><view class="panel-title">把一个真实问题，变成第一次尝试。</view><view class="muted">先从一个小问题开始；练习卡不发送内容，请勿填写客户隐私。</view><view class="reference" @click="openById('55521525252258854')">案例里的启发：先找现场问题，收紧范围，再观察工具是否被使用。查看工厂案例 ↗</view><view v-for="field in fdeFields" :key="field.key" class="field"><text>{{ field.label }}</text><textarea :value="fde[field.key]" :placeholder="field.placeholder" :maxlength="600" @input="setFde(field.key,$event)"/></view><view class="subheading">今天可以先做这 3 步</view><checkbox-group @change="setFdeSteps"><label v-for="(step,i) in fdeSteps" :key="step" class="check"><checkbox :value="String(i)" :checked="fde.steps[i]" color="#325d3e"/><text>{{ step }}</text></label></checkbox-group><view class="output-label">根据填写内容整理的提示词</view><text class="output output-text" selectable>{{ fdePrompt }}</text><button class="primary" @click="copyText(fdePrompt)">复制提示词</button><view class="privacy">提示词可自行粘贴到常用 AI 工具；实际效果与费用需自行核实。</view></view>

      <view v-if="view==='video'" class="panel"><text class="eyebrow">VIDEO BRIEF / 视频需求单</text><view class="panel-title">先把客户需求聊清楚。</view><view class="muted">填多少都可以；不确定的地方先留空。请勿填写客户隐私。</view><view v-for="field in videoFields" :key="field.key" class="field"><text>{{ field.label }}</text><textarea :value="video[field.key]" :placeholder="field.placeholder" :maxlength="600" @input="setVideo(field.key,$event)"/></view><view class="output-label">交付清单</view><text class="output output-text" selectable>{{ videoBrief }}</text><button class="primary" @click="copyText(videoBrief)">复制交付清单</button><view class="output-label">AI 提示词</view><text class="output output-text" selectable>{{ videoPrompt }}</text><button class="secondary" @click="copyText(videoPrompt)">复制 AI 提示词</button><view class="privacy">内容保存在当前设备，不通过此表单发送。最终交付以双方确认的约定为准。</view></view>

      <view v-if="view==='return'" class="panel"><text class="eyebrow">YOUR READING DESK</text><view class="panel-title">回来，接着探索。</view><view class="muted">{{ feedMeta.lastSuccessLabel ? '上次成功更新 '+feedMeta.lastSuccessLabel : '暂无成功同步时间' }} · {{ feedMeta.statusText }}</view><view class="return-box"><view class="subheading">上次读到</view><view v-if="lastArticle" class="reading-link" @click="openArticle(lastArticle)">{{ lastArticle.title }} ↗</view><view v-else class="muted">{{ lastArticleId?'这篇内容暂不在当前收录中。':'打开一篇文章，回来时可以从这里继续。' }}</view></view><view class="subheading">关注你感兴趣的方向</view><view class="topic-buttons"><view v-for="topic in topics" :key="topic.id" :class="['topic-button',{selected:followed.includes(topic.id)}]" @click="toggleTopic(topic.id)">{{ followed.includes(topic.id)?'✓ ':'' }}{{ topic.label }}</view></view><view v-if="freshArticles.length"><view class="output-label">上次访问后发布 · {{ freshArticles.length }} 篇</view><view v-for="item in freshArticles.slice(0,3)" :key="item.id" class="reading-link" @click="openArticle(item)">{{ item.title }} ↗</view></view><view v-else class="muted return-message">{{ freshMessage }}</view><view class="privacy">关注与阅读记录保存在当前设备，专题按标题和已有标签近似匹配。</view></view>
      <view class="camp" @click="goCamp"><image :src="campaign.posterUrl" mode="aspectFit"/><view><text class="eyebrow">下一步 · 动手试试</text><view class="camp-title">想系统了解 AI 实战？</view><view class="muted">了解 AI 成万事三天体验营，具体时间和参与方式以入口说明为准。</view><view class="camp-link">了解体验营 ↗</view></view></view>
    </view>
  <SiteFooter /></view>
</template>

<script setup>
import SiteFooter from '../../components/SiteFooter.vue';
import {computed, reactive, ref} from 'vue';
import {onLoad,onShow} from '@dcloudio/uni-app';
import {articles,campaign,feedMeta,isAiArticle} from '../../data/content.js';
import SiteHeader from '../../components/SiteHeader.vue';
const tabs=[{id:'quiz',label:'AI 方向测试'},{id:'fde',label:'拆解业务问题'},{id:'video',label:'视频需求单'},{id:'return',label:'回来接着看'}];
const view=ref('quiz'), quizStep=ref(-1), answers=reactive({});
const questions=[
 {id:'goal',eyebrow:'你的目标',title:'你希望 AI 先帮你做什么？',options:[{value:'side',label:'探索副业',detail:'看看有没有可以尝试的方向'},{value:'work',label:'提高工作效率',detail:'把重复工作做得更顺手'},{value:'business',label:'服务客户或企业',detail:'从真实需求里找机会'},{value:'product',label:'做自己的产品',detail:'把一个想法做出来'}]},
 {id:'interest',eyebrow:'你的兴趣',title:'哪种事情更让你想动手？',options:[{value:'content',label:'做内容',detail:'视频、图文与创意表达'},{value:'tools',label:'搭工具',detail:'智能体、工作流与应用'},{value:'customers',label:'聊需求',detail:'获客、销售与客户问题'},{value:'delivery',label:'解决业务问题',detail:'和企业一起寻找落地办法'}]},
 {id:'skill',eyebrow:'目前的基础',title:'你现在的技术经验是？',options:[{value:'beginner',label:'刚开始了解',detail:'希望从容易理解的内容看起'},{value:'user',label:'用过一些 AI 工具',detail:'想进一步找到自己的场景'},{value:'builder',label:'会一点技术或编程',detail:'愿意搭建、测试和迭代'}]},
 {id:'time',eyebrow:'可用的时间',title:'一周大约能投入多少时间？',options:[{value:'little',label:'少于 3 小时',detail:'先利用碎片时间了解'},{value:'some',label:'3—8 小时',detail:'可以安排一些实践'},{value:'more',label:'8 小时以上',detail:'愿意持续投入研究'}]},
 {id:'budget',eyebrow:'投入偏好',title:'你希望先怎样投入？',options:[{value:'low',label:'尽量少投入',detail:'先了解，再决定是否付费'},{value:'flexible',label:'看情况投入',detail:'如果方向合适，可以逐步尝试'},{value:'unsure',label:'还没想好',detail:'先看案例，了解可能的选择'}]},
];
const directions=[{id:'content',title:'AI 内容创作',reason:'从表达与创意出发，先看 AI 视频和创作案例。',pattern:/视频|短剧|自媒体|图文|生图|创作|内容|文案|直播|剪辑|影视/i},{id:'tools',title:'AI 工具与工作流',reason:'想提高效率或动手做产品，可以先看智能体、工具和工作流。',pattern:/agent|智能体|工作流|自动化|工具|mcp|知识库|助手/i},{id:'growth',title:'AI 获客与营销',reason:'如果关注客户需求，可以看看 AI 获客和营销案例。',pattern:/获客|营销|销售|引流|询盘|增长/i},{id:'fde',title:'企业 AI 落地',reason:'想解决业务问题或服务企业，可以了解 FDE 与企业 AI 实践。',pattern:/\bfde\b|企业.{0,10}(?:落地|业务|部署|交付)/i}];
const recommendations=computed(()=>{const scores={content:0,tools:0,growth:0,fde:0};const goal={side:[['content',2],['growth',2]],work:[['tools',3]],business:[['fde',3],['growth',2]],product:[['tools',3],['fde',1]]};(goal[answers.goal]||[]).forEach(([key,n])=>scores[key]+=n);const target={content:'content',tools:'tools',customers:'growth',delivery:'fde'}[answers.interest];if(target)scores[target]+=4;if(answers.skill==='builder'){scores.tools++;scores.fde++;}if(answers.skill==='beginner')scores.content++;const used=new Set();return directions.map((d,i)=>({...d,score:scores[d.id],i})).sort((a,b)=>b.score-a.score||a.i-b.i).slice(0,3).map(d=>{const item=articles.find(a=>isAiArticle(a)&&!used.has(String(a.id))&&d.pattern.test(String(a.title||'')))||articles.find(a=>isAiArticle(a)&&!used.has(String(a.id))&&d.pattern.test([a.overview,a.summary].join(' ')));if(item)used.add(String(item.id));return {...d,article:item};});});
const readingHint=computed(()=>{const time=answers.time==='little'?'你选择了每周少于 3 小时，可以先从一篇案例的速览开始。':answers.time==='some'?'你计划每周投入 3—8 小时，可以先选一个感兴趣的案例继续研究。':'你计划每周投入 8 小时以上，可以收藏感兴趣的案例，逐步比较。';const budget=answers.budget==='low'?'你希望先控制投入，实际费用请在行动前自行核实。':answers.budget==='flexible'?'你愿意视情况逐步投入，实际费用请结合具体案例核实。':'你还在考虑投入多少，实际时间与费用请结合具体案例核实。';return `${time}${budget}`;});
function restartQuiz(){for(const k of Object.keys(answers))delete answers[k];quizStep.value=0;}
const fdeFields=[{key:'problem',label:'遇到了什么问题？',placeholder:'例如：每次订单都要手动整理，容易遗漏'},{key:'user',label:'谁会实际使用？',placeholder:'例如：每天整理订单的同事'},{key:'trial',label:'想先尝试一个什么小改进？',placeholder:'例如：先让 AI 帮忙汇总一份当天订单'}];
const fdeSteps=['找一位实际使用者，确认问题是否经常发生','只选一个小场景，想清楚一次尝试怎么完成','请使用者试一次，记下是否愿意继续使用'];
const fde=reactive({problem:'',user:'',trial:'',steps:[false,false,false]});
const videoFields=[{key:'duration',label:'视频时长',placeholder:'例如：30 秒'},{key:'format',label:'画幅 / 发布平台',placeholder:'例如：竖屏 9:16'},{key:'style',label:'画面风格',placeholder:'例如：真实温暖'},{key:'script',label:'脚本或内容方向',placeholder:'例如：介绍产品使用场景'},{key:'sample',label:'首段样片确认方式',placeholder:'例如：先确认前 5 秒的风格'},{key:'revisions',label:'包含修改次数',placeholder:'例如：包含 2 次调整'},{key:'price',label:'报价（选填）',placeholder:'例如：500 元'},{key:'cost',label:'预计制作成本（选填）',placeholder:'例如：工具费、素材费与人工时间'}];
const video=reactive(Object.fromEntries(videoFields.map(f=>[f.key,''])));
const fdePrompt=computed(()=>`我正在尝试用 AI 改进一个工作场景，请帮助梳理需求，不要假设我已经具备资源或技术条件。\n\n遇到的问题：${fde.problem.trim()||'待填写'}\n实际使用的人：${fde.user.trim()||'待填写'}\n想先做的最小尝试：${fde.trial.trim()||'待填写'}\n\n请复述问题，列出需要向使用者确认的问题，提出范围尽量小的第一版和试用检查清单；不确定的地方明确标注，不要编造成本、效果或收益。`);
const videoBrief=computed(()=>['AI 视频定制 · 需求与交付清单',...videoFields.map(f=>`${f.label.replace('（选填）','')}：${video[f.key].trim()||'待确认'}`),'备注：以上为沟通草稿，最终以双方确认的约定为准。'].join('\n'));
const videoPrompt=computed(()=>`请根据以下客户需求整理 AI 视频制作方案。\n\n${videoBrief.value}\n\n请列出需求确认问题、制作步骤、样片检查点、交付前检查项与可能的成本。未提供的信息请标记“待确认”，不要编造客户要求或承诺结果。`);
function store(key,value){try{uni.setStorageSync(key,value);}catch{uni.showToast({title:'保存失败，请检查设备空间',icon:'none'});}}
function read(key,fallback){try{return uni.getStorageSync(key)||fallback;}catch{return fallback;}}
function setFde(key,e){fde[key]=String(e.detail.value||'').slice(0,600);store('ainpe:practice-fde-v1',{...fde});}
function setFdeSteps(e){const values=e.detail.value||[];fde.steps=fdeSteps.map((_,i)=>values.includes(String(i)));store('ainpe:practice-fde-v1',{...fde});}
function setVideo(key,e){video[key]=String(e.detail.value||'').slice(0,600);store('ainpe:video-brief:v1',{...video});}
function copyText(data){uni.setClipboardData({data,fail(){uni.showToast({title:'复制失败，请长按文字复制',icon:'none'});}});}
const topics=[{id:'fde',label:'FDE',pattern:/\bfde\b/i},{id:'agent',label:'智能体',pattern:/agent|智能体/i},{id:'ai-video',label:'AI 视频',pattern:/视频|短剧|影视|剪辑/i},{id:'ai-growth',label:'AI 获客',pattern:/获客|营销|引流|询盘/i}];
const followed=ref([]),lastArticleId=ref(''),lastVisit=ref(null);
const lastArticle=computed(()=>articles.find(a=>String(a.id)===lastArticleId.value));
const freshArticles=computed(()=>!lastVisit.value||!followed.value.length?[]:articles.filter(a=>isAiArticle(a)&&Number(a.publishedAt)*1000>lastVisit.value&&Number(a.publishedAt)*1000<=Date.now()&&topics.some(t=>followed.value.includes(t.id)&&(t.pattern.test(String(a.title||''))||(a.topics||[]).includes(t.id)))).sort((a,b)=>Number(b.publishedAt)-Number(a.publishedAt)));
const freshMessage=computed(()=>!lastVisit.value?'选好方向，下次回来可查看上次访问后发布的相关内容。':!followed.value.length?'选择方向后，这里会显示上次访问后发布的相关内容。':Date.parse(feedMeta.sync?.lastSuccessAt||'')>=lastVisit.value?'已收录的内容中，上次访问后暂无相关新帖。':'上次访问后尚无成功同步，暂时无法判断是否有新帖。');
function toggleTopic(id){followed.value=followed.value.includes(id)?followed.value.filter(x=>x!==id):[...followed.value,id];store('ainpe:return-desk-topics',followed.value);}
function openArticle(item){store('ainpe:last-article',{id:String(item.id),openedAt:Date.now()});uni.navigateTo({url:`/pages/article/index?id=${encodeURIComponent(String(item.id))}`});}
function openById(id){const item=articles.find(a=>String(a.id)===id);if(item)openArticle(item);else uni.showToast({title:'当前未收录这篇案例',icon:'none'});}
function goCamp(){uni.navigateTo({url:'/pages/camp/index'});}
onLoad(options=>{if(tabs.some(t=>t.id===options?.view))view.value=options.view;const a=read('ainpe:practice-fde-v1',{});for(const f of fdeFields)if(typeof a[f.key]==='string')fde[f.key]=a[f.key];if(Array.isArray(a.steps))fde.steps=fdeSteps.map((_,i)=>a.steps[i]===true);const b=read('ainpe:video-brief:v1',{});for(const f of videoFields)if(typeof b[f.key]==='string')video[f.key]=b[f.key];const prev=Number(read('ainpe:return-desk-visit',0));lastVisit.value=Number.isFinite(prev)&&prev>0&&prev<=Date.now()?prev:null;store('ainpe:return-desk-visit',Date.now());const interests=read('ainpe:return-desk-topics',[]);followed.value=Array.isArray(interests)?interests.filter(id=>topics.some(t=>t.id===id)):[];});
onShow(()=>{const last=read('ainpe:last-article',{});lastArticleId.value=last?.id?String(last.id):'';});
</script>

